var ROUTES = {
  "POST /api/join": join,
  "POST /api/me": me,
  "POST /api/steps": (repo, body) => submitSteps(repo, body, /* @__PURE__ */ new Date()),
  "POST /api/nudge": (repo, body) => nudge(repo, body, /* @__PURE__ */ new Date()),
  "POST /api/general": (repo, body) => general(repo, body, /* @__PURE__ */ new Date()),
  "POST /api/attack": (repo, body) => attack(repo, body, /* @__PURE__ */ new Date())
};
async function health() {
  const url = process.env.SUPABASE_URL?.trim() ?? "";
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY?.trim() ?? "";
  let claims = {};
  try {
    claims = JSON.parse(Buffer.from(key.split(".")[1] ?? "", "base64url").toString("utf8"));
  } catch {
  }
  let database = "not checked";
  try {
    const { supabaseRepo: supabaseRepo2 } = await Promise.resolve().then(() => (init_repo(), repo_exports));
    database = await supabaseRepo2.findGameByCode("INVADE") ? "ok: INVADE game found" : "ok: INVADE game missing";
  } catch (e) {
    database = `error: ${e instanceof Error ? e.message : JSON.stringify(e)}`;
  }
  return {
    status: 200,
    json: { ok: true, data: { urlHost: url.replace(/^https?:\/\//, ""), keyLength: key.length, keyRole: claims.role ?? "unreadable", keyRef: claims.ref ?? "unreadable", database } }
  };
}
async function handleApi(method, path4, body, repo) {
  if (method.toUpperCase() === "GET" && path4.replace(/\/$/, "") === "/api/health") return health();
  const handler2 = ROUTES[`${method.toUpperCase()} ${path4.replace(/\/$/, "")}`];
  if (!handler2) return { status: 404, json: { ok: false, error: "Not found" } };
  try {
    const r = repo ?? (await Promise.resolve().then(() => (init_repo(), repo_exports))).supabaseRepo;
    const json = await handler2(r, body);
    return { status: json.ok ? 200 : 400, json };
  } catch (e) {
    const detail = e instanceof Error ? e.message : JSON.stringify(e);
    console.error(`[api] ${method} ${path4} failed: ${detail}`);
    return { status: 500, json: { ok: false, error: "Something went wrong, try again" } };
  }
}

// server/vercel.ts
async function handler(req, res) {
  const path4 = (req.url ?? "/").replace(/\?.*$/, "");
  const { status, json } = await handleApi(req.method ?? "GET", path4, req.body ?? null);
  res.status(status).json(json);
}
export {
  handler as default
};
